<?php
require __DIR__.'/../includes/bootstrap.php';$u=require_can('appointment.write');v2_require();$id=is_post()?post_int('id'):get_int('id');$a=appt_find($id);if(!$a)abort(404,'Not found','Appointment not found.');$v=$_POST;$error='';
if(is_post()){require_post();try{appt_reassign($id,post_int('doctor_id'),patient_scalar($_POST,'reason'),!empty($_POST['confirm_overlap']),(int)$u['user_id']);flash('success','Doctor reassigned. The previous assignment is retained in history.');redirect('appointments/view.php?id='.$id);}catch(DomainException $e){$error=$e->getMessage();}}
page_start('Reassign doctor',['nav'=>'appointments','subtitle'=>$a['patient_name'].' · '.$a['appointment_no'],'crumbs'=>[['Appointment','appointments/view.php?id='.$id]]]);
if($error):?><div class="alert alert-error"><?= e($error) ?></div><?php endif;?>
<form method="post" class="panel narrow"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><p>Current doctor: <strong><?= e($a['doctor_name']) ?></strong></p><p>Appointment time stays <?= e(fmt_dt($a['start_at'])) ?>.</p>
<?= f_select('doctor_id','New doctor',doctor_options(),$v,[],['placeholder'=>'Choose doctor','required'=>true]) ?><?= f_textarea('reason','Reason for reassignment',$v,[],['required'=>true]) ?><?= f_check('confirm_overlap','I reviewed any patient scheduling overlap.',!empty($v['confirm_overlap'])) ?><div class="form-actions"><button class="btn btn-primary">Reassign doctor</button><a class="btn btn-secondary" href="<?= e(url('appointments/view.php?id='.$id)) ?>">Cancel</a></div></form><?php page_end();
